Вот рабочий код на языке Go для быстрой сортировки (quicksort):
```
func q(a []int) []int {
 if len(a) < 2 { return a }; p := a[0]; l, r := []int{}, []int{}; for _, x := range a[1:] { if x < p { l = append(l, x) } else { r = append(r, x) } }; return append(append(q(l), p), q(r)...) 
}
```

Вот рабочий код на языке Go для бинарного поиска в массиве:
```
func bs(a []int, t int) int {
 l, h := 0, len(a)-1; for l <= h { m := (l+h)/2; if a[m] == t { return m }; if a[m] < t { l = m+1 } else { h = m-1 } }; return -1 
}
```

